#!/usr/bin/env node
/**
 * Regenerate the parser artifacts from the grammar definition.
 *
 * The tree-sitter CLI runs in a scratch directory, so only the grammar
 * derived artifacts are refreshed. The vendored runtime headers below
 * `src/tree_sitter` belong to the tree-sitter runtime version and are not
 * regenerated by the generator; they are replaced when the runtime version
 * changes.
 */

import { execFileSync } from 'node:child_process';
import { cpSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ARTIFACTS = ['parser.c', 'grammar.json', 'node-types.json'];

const root = fileURLToPath(new URL('..', import.meta.url));

const abi = readFileSync(join(root, 'abi-version'), 'utf8').trim();
if (!/^\d+$/.test(abi)) throw new Error(`invalid abi-version: ${abi}`);

const scratch = mkdtempSync(join(tmpdir(), 'linkrs-grammar-'));
try {
	cpSync(join(root, 'grammar.js'), join(scratch, 'grammar.js'));
	cpSync(join(root, 'tree-sitter.json'), join(scratch, 'tree-sitter.json'));
	cpSync(join(root, 'data'), join(scratch, 'data'), { recursive: true });
	cpSync(join(root, 'queries'), join(scratch, 'queries'), { recursive: true });

	execFileSync('tree-sitter', ['generate', '--abi', abi], {
		cwd: scratch,
		stdio: 'inherit',
	});

	for (const artifact of ARTIFACTS) {
		cpSync(join(scratch, 'src', artifact), join(root, 'src', artifact));
	}
} finally {
	rmSync(scratch, { recursive: true, force: true });
}

console.log(`generated ${ARTIFACTS.join(', ')} with abi=${abi}`);
